import os, json, subprocess, datetime, math
import requests
from collections import Counter

token = subprocess.check_output(['gh','auth','token']).decode().strip()
headers = {
    'Authorization': f'bearer {token}',
    'Accept': 'application/vnd.github+json'
}

def fetch_search(query, node_type):
    # node_type: 'PullRequest' or 'Issue'
    url = 'https://api.github.com/graphql'
    results = []
    cursor = None
    while True:
        gql = '''query($query:String!, $cursor:String){
          search(query:$query, type:ISSUE, first:100, after:$cursor){
            pageInfo{hasNextPage endCursor}
            nodes{
              ... on PullRequest {
                createdAt
                mergedAt
                closedAt
                state
                author{ login }
              }
              ... on Issue {
                createdAt
                closedAt
                state
                labels(first:50){ nodes { name } }
              }
            }
          }
        }'''
        variables = {'query': query, 'cursor': cursor}
        resp = requests.post(url, json={'query': gql, 'variables': variables}, headers=headers)
        resp.raise_for_status()
        data = resp.json()
        if 'errors' in data:
            raise RuntimeError(data['errors'])
        search = data['data']['search']
        nodes = search['nodes']
        for n in nodes:
            # filter to desired type
            if node_type == 'PullRequest' and 'mergedAt' in n:
                results.append(n)
            elif node_type == 'Issue' and 'labels' in n:
                results.append(n)
        if not search['pageInfo']['hasNextPage']:
            break
        cursor = search['pageInfo']['endCursor']
    return results

# Date range
start = '2024-12-01'
end = '2024-12-31'

# PRs
