pr_closed = sum(1 for pr in prs if pr.get('state') == 'CLOSED' and not pr.get('mergedAt'))

# avg merge days
if merged_prs:
    total_days = 0.0
    for pr in merged_prs:
        created = datetime.datetime.fromisoformat(pr['createdAt'].replace('Z','+00:00'))
        merged = datetime.datetime.fromisoformat(pr['mergedAt'].replace('Z','+00:00'))
        total_days += (merged - created).total_seconds() / 86400.0
    avg_merge_days = round(total_days / len(merged_prs), 1)
else:
    avg_merge_days = 0.0

# top contributor
counter = Counter()
for pr in prs:
    author = pr.get('author')
    login = author.get('login') if author else None
    if login:
        counter[login] += 1
if counter:
    top_contributor = counter.most_common(1)[0][0]
else:
    top_contributor = ''

# Issues
issue_query = f'repo:cli/cli is:issue created:{start}..{end}'
issues = fetch_search(issue_query, 'Issue')
issue_total = len(issues)

