    labels = [l['name'] for l in issue.get('labels', {}).get('nodes', [])]
    if any('bug' in name.lower() for name in labels):
        bug_issues.append(issue)
issue_bug = len(bug_issues)

# resolved bugs closed during month
start_dt = datetime.datetime.fromisoformat('2024-12-01T00:00:00+00:00')
end_dt = datetime.datetime.fromisoformat('2024-12-31T23:59:59+00:00')
resolved_bugs = 0
for issue in bug_issues:
